1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Locale;
8	import java.util.Set;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's unified {@code memberId}, formatted {@code <REGIONV2><FY><HASH8><CHK>} where:
16	 * <ul>
17	 * <li>REGIONV2 is the version-2 {@link Owner#regionCodeV2(String) region code} — the plain region
18	 * derived from the owner's postcode (see {@link Owner#regionOfPostcode(String)}, or {@code UNKNOWN}
19	 * when the postcode maps to no known region) with the fixed {@link Owner#IDENTITY_VERSION} tag mixed
20	 * in (e.g. {@code NSWV2}),</li>
21	 * <li>FY is the two-digit (zero-padded) last two digits of the fiscal year (starting 1 July) of the
22	 * business-day-adjusted {@code registrationDate},</li>
23	 * <li>HASH8 is the first 8 upper-case hex characters of the SHA-256 of the normalized telephone
24	 * concatenated with the lastName — the same region-and-hash identity used elsewhere, and</li>
25	 * <li>CHK is a single Luhn check digit computed over the digits of {@code <REGIONV2><FY><HASH8>}.</li>
26	 * </ul>
27	 * e.g. {@code NSWV2273F9A1C7E4}. Because the version-2 tag is mixed into the region code, no
28	 * version-2 member id can reproduce a version-1 value. This single value unifies the former
29	 * {@code customerCode} and {@code membershipNumber} and subsumes the standalone {@code checkDigit}.
30	 * When the computed id collides with an existing owner's {@code memberId}, {@code -<n>} is appended
31	 * with the smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSWV2273F9A1C7E4-2}).
32	 * Runs after {@link BuildOwner} builds the entity (so the telephone is in canonical E.164 form and
33	 * the business-day-adjusted registration date is set) and before {@link SaveOwner} persists it,
34	 * mutating the built owner in place so the saved and returned record carries the id. The user-facing
35	 * {@link Owner#getLocality() locality}, {@link Owner#getFiscalYear() fiscal year} and owner segment
36	 * are derived independently from the postcode and registration date, so they stay the plain region
37	 * code and never carry the version-2 tag.
38	 */
39	public class AssignOwnerMemberId {
40	
41	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
42	        String region = Owner.regionCodeV2(Owner.regionOfPostcode(owner.getPostcode()));
43	        String fy = String.format(Locale.ROOT, "%02d", Owner.fiscalYear(owner.getRegistrationDate()) % 100);
44	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
45	        String identity = region + fy + hash8;
46	        String base = identity + luhnCheckDigit(identity);
47	        owner.setMemberId(deduplicate(base, owner, ownerRepository));
48	    }
49	
50	    /**
51	     * The unique member id for the owner: {@code base} when no other owner already carries it,
52	     * otherwise {@code base-<n>} with the smallest {@code n} of 2 or more that is not yet taken.
53	     * The owner is not yet persisted, so its own id is excluded by identity.
54	     */
55	    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
56	        Set<String> taken = new HashSet<>();
57	        for (Owner existing : ownerRepository.findAll()) {
58	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
59	                continue;
60	            }
61	            String id = existing.getMemberId();
62	            if (id != null) {
63	                taken.add(id);
64	            }
65	        }
66	        if (!taken.contains(base)) {
67	            return base;
68	        }
69	        int n = 2;
70	        while (taken.contains(base + "-" + n)) {
71	            n++;
72	        }
73	        return base + "-" + n;
74	    }
75	
76	    /**
77	     * The first 8 upper-case hex characters of the SHA-256 digest of {@code value}, taken over its
78	     * UTF-8 bytes — i.e. the first 4 digest bytes rendered as hex.
79	     */
80	    private static String sha256Hex8(String value) {
81	        try {
82	            byte[] digest = MessageDigest.getInstance("SHA-256")
83	                    .digest(value.getBytes(StandardCharsets.UTF_8));
84	            StringBuilder sb = new StringBuilder(8);
85	            for (int i = 0; i < 4; i++) {
86	                sb.append(String.format(Locale.ROOT, "%02X", digest[i]));
87	            }
88	            return sb.toString();
89	        }
90	        catch (NoSuchAlgorithmException ex) {
91	            throw new IllegalStateException("SHA-256 not available", ex);
92	        }
93	    }
94	
95	    /**
96	     * A single Luhn check digit (0-9) over the digits contained in {@code value} (non-digit
97	     * characters are ignored): doubling every second digit from the right, subtracting 9 from any
98	     * result over 9, and taking {@code (10 - sum % 10) % 10}.
99	     */
100	    private static int luhnCheckDigit(String value) {
101	        int sum = 0;
102	        boolean dbl = true;
103	        for (int i = value.length() - 1; i >= 0; i--) {
104	            char c = value.charAt(i);
105	            if (c < '0' || c > '9') {
106	                continue;
107	            }
108	            int d = c - '0';
109	            if (dbl) {
110	                d *= 2;
111	                if (d > 9) {
112	                    d -= 9;
113	                }
114	            }
115	            sum += d;
116	            dbl = !dbl;
117	        }
118	        return (10 - (sum % 10)) % 10;
119	    }
120	}
